"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4255],{85424:e=>{e.exports=JSON.parse('{"functions":[{"name":"log","desc":"Logs an event. Safe to call from either realm.\\n\\nOn the client the payload is forwarded to the server and this returns\\nimmediately. On the server `data.player` is required \u2014 an event without one is\\ndiscarded.\\n\\nInvalid payloads are dropped without raising, so this never needs to be wrapped in\\na `pcall` on a hot path.","params":[{"name":"data","desc":"Event to log","lua_type":"BaseEvent"}],"returns":[],"function_type":"static","source":{"line":246,"path":"src/Shared/Class/Analytics.luau"}},{"name":"logPlayerEvent","desc":"The name core\'s services use for [Analytics.log].","params":[{"name":"data","desc":"Event to log","lua_type":"BaseEvent"}],"returns":[],"function_type":"static","source":{"line":285,"path":"src/Shared/Class/Analytics.luau"}},{"name":"logResourceEvent","desc":"Logs a currency change as a Roblox economy event (`LogEconomyEvent`).","params":[{"name":"data","desc":"The currency change","lua_type":"ResourceEvent"}],"returns":[],"function_type":"static","realm":["Server"],"source":{"line":296,"path":"src/Shared/Class/Analytics.luau"}},{"name":"logPlayerProgression","desc":"Logs a progression step (`LogProgressionEvent`). An `eventId` of\\n`\\"Onboarding\\"` logs a step of Roblox\'s onboarding funnel instead\\n(`LogOnboardingFunnelStepEvent`).","params":[{"name":"data","desc":"The progression step","lua_type":"ProgressionEvent"}],"returns":[],"function_type":"static","realm":["Server"],"source":{"line":339,"path":"src/Shared/Class/Analytics.luau"}},{"name":"logFunnelStep","desc":"Logs a step of a custom funnel (`LogFunnelStepEvent`). Roblox counts a\\nstep once per `sessionId`, and a step logged after a skipped one completes\\nthe skipped one too.","params":[{"name":"data","desc":"The funnel step","lua_type":"FunnelStepEvent"}],"returns":[],"function_type":"static","realm":["Server"],"source":{"line":388,"path":"src/Shared/Class/Analytics.luau"}},{"name":"addTrackedValue","desc":"Does nothing: per-player counters aren\'t sent. Log a count that matters with\\n[Analytics.log] once, when its activity ends.","params":[{"name":"_data","desc":"","lua_type":"BaseEvent"}],"returns":[],"function_type":"static","source":{"line":421,"path":"src/Shared/Class/Analytics.luau"}},{"name":"logMarketplacePurchase","desc":"Does nothing: Roblox records Robux purchases itself.","params":[{"name":"_data","desc":"","lua_type":"unknown"}],"returns":[],"function_type":"static","realm":["Server"],"source":{"line":433,"path":"src/Shared/Class/Analytics.luau"}},{"name":"logSession","desc":"Does nothing: Roblox records sessions itself.","params":[{"name":"_player","desc":"","lua_type":"Player"},{"name":"_values","desc":"","lua_type":"unknown"}],"returns":[],"function_type":"static","realm":["Server"],"source":{"line":446,"path":"src/Shared/Class/Analytics.luau"}},{"name":"start","desc":"Does nothing: Roblox\'s analytics need no keys or setup.","params":[{"name":"_options","desc":"","lua_type":"unknown"}],"returns":[],"function_type":"static","realm":["Server"],"source":{"line":458,"path":"src/Shared/Class/Analytics.luau"}}],"properties":[],"types":[{"name":"BaseEvent","desc":"One analytics event. Anything failing validation \u2014 a missing event name, a\\nnegative value \u2014 is dropped silently rather than erroring.","fields":[{"name":"event","lua_type":"string","desc":"Colon-delimited event name; see the class description"},{"name":"player","lua_type":"Player?","desc":"Required on the server; filled in automatically for client calls"},{"name":"value","lua_type":"number?","desc":"Non-negative magnitude, defaults to 1"}],"source":{"line":68,"path":"src/Shared/Class/Analytics.luau"}},{"name":"ResourceEvent","desc":"One currency change, logged as a Roblox economy event.","fields":[{"name":"player","lua_type":"Player","desc":""},{"name":"eventType","lua_type":"string?","desc":"Transaction type, `\\"Gameplay\\"` when nil"},{"name":"itemId","lua_type":"string","desc":"What the currency was spent on or earned from"},{"name":"currency","lua_type":"string","desc":""},{"name":"amount","lua_type":"number","desc":"Logged as its absolute value"},{"name":"endingBalance","lua_type":"number?","desc":"The player\'s balance afterwards, 0 when nil"},{"name":"flowType","lua_type":"(\\"Sink\\" | \\"Source\\")?","desc":"`\\"Sink\\"` when nil"}],"source":{"line":87,"path":"src/Shared/Class/Analytics.luau"}},{"name":"ProgressionEvent","desc":"One progression step, logged as a Roblox progression event or onboarding funnel\\nstep.","fields":[{"name":"player","lua_type":"Player","desc":""},{"name":"eventId","lua_type":"string","desc":"Progression path; `\\"Onboarding\\"` logs Roblox\'s onboarding funnel"},{"name":"status","lua_type":"\\"Start\\" | \\"Fail\\" | \\"Complete\\"","desc":"Unused by the onboarding funnel"},{"name":"step","lua_type":"number","desc":""},{"name":"stepName","lua_type":"string","desc":""}],"source":{"line":109,"path":"src/Shared/Class/Analytics.luau"}},{"name":"FunnelStepEvent","desc":"One step of a custom funnel, logged as a Roblox funnel step event.","fields":[{"name":"player","lua_type":"Player","desc":""},{"name":"funnelName","lua_type":"string","desc":""},{"name":"sessionId","lua_type":"string","desc":"Tells one run of the funnel from another for the same player"},{"name":"step","lua_type":"number","desc":""},{"name":"stepName","lua_type":"string","desc":""}],"source":{"line":128,"path":"src/Shared/Class/Analytics.luau"}}],"name":"Analytics","desc":"Logs events to Roblox\'s [AnalyticsService], from either realm: custom events,\\neconomy events and progression events. It also answers to the function names\\ncore\'s services call (`logPlayerEvent`, `logResourceEvent`,\\n`logPlayerProgression`, and the no-ops below), so they need no changes.\\n\\n`LogCustomEvent` is server-only, so this module carries a RemoteEvent: a client\\ncall forwards the payload to the server, which stamps the sending player onto it\\nand logs it. The server trusts the client for the event name and value but never\\nfor the player, so a client cannot log events against someone else. Economy and\\nprogression events are server-only; a client call does nothing.\\n\\nEvent names are colon-delimited to pack extra dimensions into Roblox\'s three\\ncustom field slots. `\\"Shop:Purchase:Coins\\"` logs as event `\\"Shop\\"` with\\n`CustomField01 = \\"Purchase\\"` and `CustomField02 = \\"Coins\\"`. Segments past the\\nthird are dropped, and anything outside `[A-Za-z0-9-_. :]` becomes an underscore.\\n\\nIn Studio the server also prints every event it sends to Output, because\\nCreator Hub\'s dashboards lag behind events by up to a day.\\n\\n```lua\\nAnalytics.log({ event = \\"Shop:Purchase:Coins\\", player = player, value = 250 })\\n```\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":30,"path":"src/Shared/Class/Analytics.luau"}}')}}]);